<?php include 'verifica_login.php'; if (!validar_csrf($_GET['csrf_token'] ?? null)) { http_response_code(403); exit('Solicitação inválida.'); } include 'conexao.php';$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);if(!$id||$id<1)die('ID inválido.');mysqli_begin_transaction($conexao);try{$q=mysqli_query($conexao,"SELECT id_inscricao FROM inscricoes WHERE id_concurso=$id");if(!$q)throw new Exception(mysqli_error($conexao));while($i=mysqli_fetch_assoc($q)){ $iid=(int)$i['id_inscricao'];if(!mysqli_query($conexao,"DELETE FROM resultados WHERE id_inscricao=$iid"))throw new Exception(mysqli_error($conexao)); }if(!mysqli_query($conexao,"DELETE FROM inscricoes WHERE id_concurso=$id"))throw new Exception(mysqli_error($conexao));if(!mysqli_query($conexao,"DELETE FROM concursos WHERE id_concurso=$id"))throw new Exception(mysqli_error($conexao));mysqli_commit($conexao);header('Location: lista_concursos.php');exit;}catch(Exception $e){mysqli_rollback($conexao);die('Não foi possível excluir o concurso: '.htmlspecialchars($e->getMessage()));}
